import 'dart:async';
import 'dart:convert';
import 'dart:math';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Every sound effect in the game. Files live in assets/sounds and are
/// generated by tool/sound/render.js (see docs/SOUNDS.md).
enum Sfx {
  sweep('sweep'),
  pickup('pickup'),
  invalid('invalid'),
  perfect('perfect'),
  gameover('gameover'),
  revive('revive'),
  coin('coin'),
  levelup('levelup'),
  tap('tap');

  const Sfx(this.file);

  /// Asset file name without the extension. Spelled out rather than taken
  /// from the enum's name, so release builds with obfuscation stay safe.
  final String file;
}

/// Plays sound effects and the background music.
abstract class SoundService {
  Future<void> init();

  bool soundOn = true;
  bool musicOn = true;

  void play(Sfx sfx);

  /// Soft "tock" when a block lands, with a little random pitch variety.
  void place();

  /// A line clear: the combo chime (its pitch climbs with [combo]), the
  /// sweep, and for 2+ lines at once a bigger sound for every extra line.
  /// A [perfect] clear plays its own sound instead of the multi-line one.
  void clear({required int lines, required int combo, bool perfect = false});

  /// How loud the combo chime plays under bigger moments, so the stacked
  /// sounds keep their headroom (checked against every combination of
  /// lines, combo and placement sound) and the bigger sound leads.
  static double chimeVolume(int lines, {bool perfect = false}) {
    if (perfect || lines >= 5) return 0.6;
    if (lines == 4) return 0.7;
    if (lines >= 2) return 0.85;
    return 1.0;
  }

  /// The multi-line sound for [lines] cleared at once, or null for one line.
  static String? linesFile(int lines) =>
      lines >= 2 ? 'lines_${lines.clamp(2, 6)}' : null;

  /// Applies [musicOn] and app foreground state.
  void updateMusic({bool appInForeground = true});

  static SoundService create() => AudioplayersSoundService();
}

/// Silent implementation for tests.
class SilentSoundService extends SoundService {
  final played = <String>[];
  @override
  Future<void> init() async {}
  @override
  void play(Sfx sfx) => played.add(sfx.file);
  @override
  void place() => played.add('place');
  @override
  void clear({required int lines, required int combo, bool perfect = false}) {
    played.add('clear$combo');
    final multi = SoundService.linesFile(lines);
    if (multi != null && !perfect) played.add(multi);
  }

  @override
  void updateMusic({bool appInForeground = true}) {}
}

class AudioplayersSoundService extends SoundService {
  final _pools = <String, AudioPool>{};
  final _random = Random();
  AudioPlayer? _music;
  bool _ready = false;

  /// In-game volume of each file, from assets/sounds/mix.json (written by the
  /// Sound Studio renderer). Falls back to these values if it can't be read.
  final Map<String, double> _mix = {
    'pickup': 0.5,
    'invalid': 0.6,
    'tap': 0.7,
    'coin': 0.8,
    'sweep': 0.7,
    for (var n = 2; n <= 6; n++) 'lines_$n': 0.85,
    'music_loop': 0.35,
  };

  @override
  Future<void> init() async {
    try {
      final json = await rootBundle.loadString('assets/sounds/mix.json');
      final data = jsonDecode(json) as Map<String, dynamic>;
      data.forEach((k, v) => _mix[k] = (v as num).toDouble());
    } catch (e) {
      debugPrint('Sound mix unavailable, using defaults: $e');
    }
    try {
      // Mix with whatever the player is already listening to (podcasts,
      // their own music) instead of pausing it, and respect the silent switch.
      await AudioPlayer.global.setAudioContext(
        AudioContextConfig(
          focus: AudioContextConfigFocus.mixWithOthers,
          respectSilence: true,
        ).build(),
      );
      final names = [
        for (var i = 0; i < 3; i++) 'place_$i',
        for (var i = 1; i <= 8; i++) 'clear_$i',
        for (var n = 2; n <= 6; n++) 'lines_$n',
        for (final s in Sfx.values) s.file,
      ];
      for (final name in names) {
        _pools[name] = await AudioPool.createFromAsset(
          path: 'sounds/$name.wav',
          maxPlayers: name.startsWith('place') || name == 'pickup' ? 3 : 2,
        );
      }
      _ready = true;
      updateMusic();
    } catch (e) {
      // Sound is a nice-to-have: never let it break the game.
      debugPrint('Sound unavailable: $e');
    }
  }

  void _play(String name, [double volume = 1.0]) {
    if (!_ready || !soundOn) return;
    final pool = _pools[name];
    if (pool == null) return;
    unawaited(
      pool
          .start(volume: volume * (_mix[name] ?? 1.0))
          .catchError((_) => () async {}),
    );
  }

  @override
  void play(Sfx sfx) => _play(sfx.file);

  @override
  void place() => _play('place_${_random.nextInt(3)}');

  @override
  void clear({required int lines, required int combo, bool perfect = false}) {
    _play(
      'clear_${combo.clamp(1, 8)}',
      SoundService.chimeVolume(lines, perfect: perfect),
    );
    _play('sweep');
    final multi = SoundService.linesFile(lines);
    if (multi != null && !perfect) _play(multi);
  }

  @override
  void updateMusic({bool appInForeground = true}) {
    if (!_ready) return;
    final shouldPlay = musicOn && appInForeground;
    unawaited(() async {
      try {
        if (shouldPlay) {
          final player = _music ??= AudioPlayer();
          await player.setReleaseMode(ReleaseMode.loop);
          await player.setVolume(_mix['music_loop'] ?? 0.35);
          if (player.state == PlayerState.paused) {
            await player.resume();
          } else if (player.state != PlayerState.playing) {
            await player.play(AssetSource('sounds/music_loop.wav'));
          }
        } else {
          await _music?.pause();
        }
      } catch (e) {
        debugPrint('Music unavailable: $e');
      }
    }());
  }
}
